WITH filtered AS (SELECT id, full_name, dept_id, manager_id, job_title, hire_date, REGEXP_REPLACE(email, ' ', '_') email_slug, ROUND(salary * 100, 2) adjusted_salary FROM employees WHERE hire_date >= DATE '2023-07-07' AND email LIKE '%@gmail.com') SELECT * FROM (SELECT manager_id, job_title, adjusted_salary FROM filtered) src PIVOT (AVG(adjusted_salary) AS total, COUNT(1) AS n FOR job_title IN ('Designer' AS designer, 'Manager' AS manager, 'Intern' AS intern));
